#include <stdio.h>

void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

void addBonus(int arr[], int size, int bonus) {
    for (int i = 0; i < size; i++) {
        arr[i] += bonus;
    }
}

int main() {
    int marks[] = {78, 92, 65, 88, 71};
    int n = sizeof(marks) / sizeof(marks[0]);

    printArray(marks, n);
    addBonus(marks, n, 5);
    printArray(marks, n);
    return 0;
}

